local RollingPinMaker = {}
local PRODUCTS = {
    iron_rolling_pin = { name = "Železni valjek za testo", ironCost = 1, woodCost = 3, leatherCost = 1, time = 4, cost = 130, prestige = 3, happiness = 2, description = "Železni valjek za razvaljavanje testa." },
    bronze_rolling_pin = { name = "Bronast valjek za testo", bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 6, cost = 320, prestige = 5, happiness = 3, description = "Bronast valjek za pekarno." },
    silver_rolling_pin = { name = "Srebrni valjek za testo", silverCost = 1, bronzeCost = 1, ironCost = 1, woodCost = 3, leatherCost = 1, time = 10, cost = 780, prestige = 10, happiness = 4, description = "Srebrni valjek za plemiške kuharje." },
    gilded_rolling_pin = { name = "Pozlačeni valjek za testo", goldCost = 1, silverCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 14, cost = 1700, prestige = 19, happiness = 5, description = "Pozlačeni valjek za dvorne kuharje." },
    jewel_set_rolling_pin = { name = "Draguljasti valjek za testo", goldCost = 2, silverCost = 1, jewelCost = 1, bronzeCost = 1, woodCost = 3, leatherCost = 1, time = 18, cost = 3700, prestige = 35, happiness = 7, description = "Draguljasti valjek za kraljeve kuharje." },
    royal_sovereign_rolling_pin = { name = "Kraljevski suvereni valjek za testo", goldCost = 3, silverCost = 3, jewelCost = 2, pearlCost = 2, bronzeCost = 1, woodCost = 4, leatherCost = 1, time = 25, cost = 8000, prestige = 67, happiness = 13, description = "Suvereni valjek z biseri za krono." },
}
local BUILDINGS = {
    rollingpin_workshop = { name = "Valjarska delavnica", cost = { gold = 300, wood = 180, stone = 125, iron = 6 }, upkeep = 5, qualityBonus = 5 },
    rollingpin_house = { name = "Valjarska hiša", cost = { gold = 1110, wood = 360, stone = 255, silver = 6, iron = 6 }, upkeep = 23, qualityBonus = 18 },
    master_rollingpin_atelier = { name = "Mojstrski valjarski atelje", cost = { gold = 2850, wood = 420, stone = 495, silver = 32, gold = 6 }, upkeep = 67, qualityBonus = 30 },
    sovereign_rollingpin_palace = { name = "Suverena valjarska palača", cost = { gold = 12400, wood = 640, stone = 800, gold = 79, jewel = 18 }, upkeep = 245, qualityBonus = 55, prestigeBonus = 50 },
}
RollingPinMaker.ironStock = 10; RollingPinMaker.bronzeStock = 8; RollingPinMaker.woodStock = 18; RollingPinMaker.leatherStock = 8; RollingPinMaker.silverStock = 8; RollingPinMaker.goldStock = 6; RollingPinMaker.jewelStock = 4; RollingPinMaker.pearlStock = 4
RollingPinMaker.productStock = {}; RollingPinMaker.buildings = {}; RollingPinMaker.maker = nil; RollingPinMaker.activeMaking = {}; RollingPinMaker.totalProducts = 0; RollingPinMaker.dayTimer = 0
function RollingPinMaker.init() RollingPinMaker.ironStock=10; RollingPinMaker.bronzeStock=8; RollingPinMaker.woodStock=18; RollingPinMaker.leatherStock=8; RollingPinMaker.silverStock=8; RollingPinMaker.goldStock=6; RollingPinMaker.jewelStock=4; RollingPinMaker.pearlStock=4; RollingPinMaker.productStock={}; RollingPinMaker.buildings={}; RollingPinMaker.maker=nil; RollingPinMaker.activeMaking={}; RollingPinMaker.totalProducts=0; RollingPinMaker.dayTimer=0; print("[RollingPinMaker] Royal Rolling Pin Maker System initialized (6 products, 4 buildings)") end
function RollingPinMaker.hireMaker(n,s) s=s or math.random(55,90); local c=570+s*12; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; RollingPinMaker.maker={name=n or ("Valjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjar najet: %s (spretnost: %d)",RollingPinMaker.maker.name,s),"success") end; return true end
function RollingPinMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function RollingPinMaker.build(id) local ok,e=RollingPinMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(RollingPinMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function RollingPinMaker.getQualityBonus() local b=0; for _,bd in ipairs(RollingPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function RollingPinMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.ironCost and RollingPinMaker.ironStock<(d.ironCost or 0) then return false,"Premalo železa" end; if d.bronzeCost and RollingPinMaker.bronzeStock<(d.bronzeCost or 0) then return false,"Premalo brona" end; if d.woodCost and RollingPinMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.leatherCost and RollingPinMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and RollingPinMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and RollingPinMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and RollingPinMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and RollingPinMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #RollingPinMaker.buildings==0 then return false,"Potrebna valjarska delavnica" end; if not RollingPinMaker.maker then return false,"Potreben valjar" end; return true end
function RollingPinMaker.make(pt,qty) qty=qty or 1; local ok,e=RollingPinMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.ironCost then RollingPinMaker.ironStock=RollingPinMaker.ironStock-d.ironCost*qty end; if d.bronzeCost then RollingPinMaker.bronzeStock=RollingPinMaker.bronzeStock-d.bronzeCost*qty end; if d.woodCost then RollingPinMaker.woodStock=RollingPinMaker.woodStock-d.woodCost*qty end; if d.leatherCost then RollingPinMaker.leatherStock=RollingPinMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then RollingPinMaker.silverStock=RollingPinMaker.silverStock-d.silverCost*qty end; if d.goldCost then RollingPinMaker.goldStock=RollingPinMaker.goldStock-d.goldCost*qty end; if d.jewelCost then RollingPinMaker.jewelStock=RollingPinMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then RollingPinMaker.pearlStock=RollingPinMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if RollingPinMaker.maker then t=math.max(1,t-math.floor(RollingPinMaker.maker.skill/13)) end; table.insert(RollingPinMaker.activeMaking,{id="rollingpin_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,food=0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function RollingPinMaker.completeMaking(m) local q=1.0+(RollingPinMaker.getQualityBonus()/100); if RollingPinMaker.maker then q=q+(RollingPinMaker.maker.skill/140) end; q=math.min(2.5,q); RollingPinMaker.productStock[m.productType]=(RollingPinMaker.productStock[m.productType] or 0)+m.quantity; RollingPinMaker.totalProducts=RollingPinMaker.totalProducts+m.quantity; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if RollingPinMaker.maker then RollingPinMaker.maker.itemsMade=RollingPinMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then RollingPinMaker.maker.skill=math.min(100,RollingPinMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Valjek izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"rollingpin.completed",{productName=m.productName,prestige=m.prestige,happiness:m.happiness}) end end
function RollingPinMaker.update(dt) if not _G.state then return end; RollingPinMaker.dayTimer=RollingPinMaker.dayTimer+dt; if RollingPinMaker.dayTimer>=30 then RollingPinMaker.dayTimer=0; for i=#RollingPinMaker.activeMaking,1,-1 do local m=RollingPinMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then RollingPinMaker.completeMaking(m); table.remove(RollingPinMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(RollingPinMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if RollingPinMaker.maker then tu=tu+15 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function RollingPinMaker.getStats() return {ironStock=RollingPinMaker.ironStock,bronzeStock=RollingPinMaker.bronzeStock,woodStock=RollingPinMaker.woodStock,leatherStock=RollingPinMaker.leatherStock,silverStock=RollingPinMaker.silverStock,goldStock=RollingPinMaker.goldStock,jewelStock=RollingPinMaker.jewelStock,pearlStock=RollingPinMaker.pearlStock,productStock=RollingPinMaker.productStock,numBuildings=#RollingPinMaker.buildings,hasMaker=RollingPinMaker.maker~=nil,makerName=RollingPinMaker.maker and RollingPinMaker.maker.name or "—",makerSkill=RollingPinMaker.maker and RollingPinMaker.maker.skill or 0,activeMaking=#RollingPinMaker.activeMaking,totalProducts=RollingPinMaker.totalProducts} end
return RollingPinMaker
